package ru.wolf.api.loadcurve;
import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import ru.wolf.api.loadcurve.dto.*; import java.util.List;
@RestController @RequiredArgsConstructor public class LoadCurveController { private final LoadCurveService service; @GetMapping("/api/v1/projects/{id}/load-curve") public List<LoadCurveResponse> project(Authentication a,@PathVariable Long id){return service.project(a.getName(),id);} @GetMapping("/api/v1/routines/{id}/load-curve") public List<LoadCurveResponse> routine(Authentication a,@PathVariable Long id){return service.routine(a.getName(),id);} @PutMapping("/api/v1/projects/{id}/load-curve") public LoadCurveResponse putProject(Authentication a,@PathVariable Long id,@Valid @RequestBody LoadCurveRequest r){return service.putProject(a.getName(),id,r);} @PutMapping("/api/v1/routines/{id}/load-curve") public LoadCurveResponse putRoutine(Authentication a,@PathVariable Long id,@Valid @RequestBody LoadCurveRequest r){return service.putRoutine(a.getName(),id,r);} @DeleteMapping("/api/v1/projects/{id}/load-curve/{entryId}") public ResponseEntity<Void> deleteProject(Authentication a,@PathVariable Long id,@PathVariable Long entryId){return service.deleteProject(a.getName(),id,entryId);} @DeleteMapping("/api/v1/routines/{id}/load-curve/{entryId}") public ResponseEntity<Void> deleteRoutine(Authentication a,@PathVariable Long id,@PathVariable Long entryId){return service.deleteRoutine(a.getName(),id,entryId);}}
